// src/lib/firebase.ts
// central Firebase setup for Sylor

import { getApps, getApp, initializeApp, type FirebaseApp } from "firebase/app";
import {
  getAuth,
  setPersistence,
  browserLocalPersistence,
  type Auth,
} from "firebase/auth";
import { getFirestore, type Firestore } from "firebase/firestore";

// read from env (you already have .env.local)
const firebaseConfig = {
  apiKey: process.env.NEXT_PUBLIC_FIREBASE_API_KEY!,
  authDomain: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN!,
  projectId: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID!,
  storageBucket: process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET!,
  messagingSenderId: process.env.NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID!,
  appId: process.env.NEXT_PUBLIC_FIREBASE_APP_ID!,
};

// 1) create / reuse app (SSR safe)
function createFirebaseApp(): FirebaseApp {
  if (typeof window === "undefined") {
    // on the server just reuse or init once
    return getApps().length ? getApp() : initializeApp(firebaseConfig);
  }
  // on client
  return getApps().length ? getApp() : initializeApp(firebaseConfig);
}

const app = createFirebaseApp();

// 2) Firestore – can be exported directly
export const db: Firestore = getFirestore(app);

// 3) Auth – wrap in a function so it doesn't blow up in SSR
export function getFirebaseAuth(): Auth {
  const auth = getAuth(app);
  // client-only persistence
  if (typeof window !== "undefined") {
    setPersistence(auth, browserLocalPersistence).catch((err) => {
      console.warn("Firebase auth persistence error:", err);
    });
  }
  return auth;
}

// 4) expose app too (sometimes api.ts wants it)
export function getFirebaseApp(): FirebaseApp {
  return app;
}
